import { NextRequest, NextResponse } from "next/server";
import { randomBytes } from "crypto";
import { and, desc, eq } from "drizzle-orm";
import { Permission, AuditEntityType, AuditAction } from "@accessbuddy/shared";
import type { TenantSettings } from "@accessbuddy/shared";
import { attestationRequests, users } from "@accessbuddy/db";
import { getAuthUser } from "@/lib/auth";
import { resolveTenant } from "@/lib/tenant";
import { checkPermission } from "@/lib/permissions";
import { withTenant } from "@/lib/with-tenant";
import { createAuditEntry } from "@/lib/services/audit";
import { sendTemplatedEmail, buildEmailConfig } from "@/lib/services/email";
import { clientEnv } from "@/env";

/**
 * Resend the most recent pending attestation for a member. Generates a fresh
 * token (invalidating any previous link) and extends the token expiry.
 */
export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ slug: string; id: string }> }
) {
  const auth = await getAuthUser();
  if (!auth) {
    return NextResponse.json({ error: "Authentication required" }, { status: 401 });
  }

  const { slug, id: userId } = await params;
  const tenant = await resolveTenant(slug);
  if (!tenant) {
    return NextResponse.json({ error: "Organisation not found" }, { status: 404 });
  }

  const permResult = checkPermission(auth, tenant.id, Permission.RENEW);
  if (!permResult.granted) {
    return NextResponse.json({ error: permResult.reason }, { status: 403 });
  }

  const body = (await request.json().catch(() => ({}))) as {
    attestationId?: string;
  };

  const settings = tenant.settings as TenantSettings;
  const tokenExpiryDays = settings.attestationTokenExpiryDays ?? 7;

  try {
    const result = await withTenant(tenant.id, async (tx) => {
      let attestation;
      if (body.attestationId) {
        const [found] = await tx
          .select()
          .from(attestationRequests)
          .where(
            and(
              eq(attestationRequests.id, body.attestationId),
              eq(attestationRequests.userId, userId),
              eq(attestationRequests.tenantId, tenant.id)
            )
          )
          .limit(1);
        attestation = found;
      } else {
        const [found] = await tx
          .select()
          .from(attestationRequests)
          .where(
            and(
              eq(attestationRequests.userId, userId),
              eq(attestationRequests.tenantId, tenant.id),
              eq(attestationRequests.status, "pending")
            )
          )
          .orderBy(desc(attestationRequests.createdAt))
          .limit(1);
        attestation = found;
      }

      if (!attestation) return null;
      if (attestation.status !== "pending") {
        throw new Error("Attestation is no longer pending");
      }

      const token = randomBytes(32).toString("hex");
      const tokenExpiresAt = new Date();
      tokenExpiresAt.setDate(tokenExpiresAt.getDate() + tokenExpiryDays);

      await tx
        .update(attestationRequests)
        .set({ token, tokenExpiresAt, updatedAt: new Date() })
        .where(eq(attestationRequests.id, attestation.id));

      const [user] = await tx
        .select({
          email: users.email,
          firstName: users.firstName,
          lastName: users.lastName,
        })
        .from(users)
        .where(eq(users.id, userId))
        .limit(1);

      if (user?.email) {
        const attestUrl = `${clientEnv.NEXT_PUBLIC_APP_URL}/t/${slug}/attest/${token}`;
        await sendTemplatedEmail(
          user.email,
          "attestationRequested",
          {
            memberName: `${user.firstName} ${user.lastName}`.trim() || "Member",
            attestUrl,
          },
          buildEmailConfig(tenant),
          undefined,
          {
            tx,
            tenantId: tenant.id,
            entityType: AuditEntityType.MEMBER,
            entityId: userId,
            actorId: auth.user.id,
          }
        );
      }

      await createAuditEntry(tx, {
        tenantId: tenant.id,
        entityType: AuditEntityType.MEMBER,
        entityId: userId,
        action: AuditAction.UPDATE,
        actorId: auth.user.id,
        metadata: {
          action: "attestation_resent",
          attestationId: attestation.id,
          season: attestation.season,
        },
      });

      return { attestationId: attestation.id, email: user?.email ?? null };
    });

    if (!result) {
      return NextResponse.json({ error: "No pending attestation found" }, { status: 404 });
    }

    return NextResponse.json({ resent: true, ...result });
  } catch (err) {
    const message = err instanceof Error ? err.message : "Internal server error";
    const status = message.includes("no longer pending") ? 400 : 500;
    return NextResponse.json({ error: message }, { status });
  }
}

