resource "google_cloud_scheduler_job" "email_queue_drain" {
  count       = var.deploy_app ? 1 : 0
  name        = "accessbuddy-email-queue-drain"
  description = "Drains the outbound email queue under the daily send budget"
  project     = var.project_id
  region      = var.region
  schedule    = "0 */2 * * *" # every 2 hours
  time_zone   = "Australia/Melbourne"

  http_target {
    http_method = "GET"
    uri         = "${google_cloud_run_v2_service.app[0].uri}/api/cron/drain-email-queue"

    headers = {
      "x-cron-secret" = var.cron_secret
    }
  }

  retry_config {
    retry_count          = 3
    min_backoff_duration = "30s"
    max_backoff_duration = "300s"
  }

  depends_on = [google_project_service.apis]
}

